const $=s=>document.querySelector(s);const media=matchMedia('(prefers-reduced-motion: reduce)');$('#reduce').checked=media.matches;function reduce(){document.body.classList.toggle('reduce',$('#reduce').checked);if($('#reduce').checked)document.getAnimations().forEach(a=>a.cancel())}reduce();$('#reduce').onchange=reduce;media.addEventListener('change',e=>{$('#reduce').checked=e.matches;reduce()});const menu=$('.menu');menu.onclick=()=>{const o=$('nav').classList.toggle('open');menu.setAttribute('aria-expanded',o);menu.setAttribute('aria-label',o?'关闭导航':'打开导航')};function closeMenu(){$('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}document.querySelectorAll('nav a').forEach(a=>a.onclick=closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));let n=0;document.querySelectorAll('.card').forEach(c=>{c.hidden=b.dataset.filter!=='全部'&&c.dataset.category!==b.dataset.filter;if(!c.hidden)n++});$('#count').textContent=n+' 个方向'});const texts=[['把日常，过成共同生活','这个方向介绍共同居住与生活实验。正式内容应提供空间照片、居住规则、价格和申请方式，让参与者在了解信息后自行决定。'],['从一个问题，认识彼此','这个方向承载主题对话和社区交流。活动详情应清楚列出主题、主持人、时间、地点和参与门槛。'],['让一个小想法，开始发生','这个方向连接有共同兴趣的人。项目页应说明想做什么、已有进展、需要怎样的参与，以及联系途径。'],['第一次参与，可以很简单','先浏览感兴趣的方向，再确认实际项目的地点、时间、费用和参与条件。这份小样不提供实际报名；它演示一个清楚、无催促的参与路径。']];function show(i){$('dialog').getAnimations().forEach(a=>a.cancel());$('dialog h2').textContent=texts[i][0];$('dialog p').textContent=texts[i][1];$('dialog').showModal();if(!$('#reduce').checked)$('dialog').animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:220,easing:'ease-out'})}document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>show(Number(b.dataset.detail)));$('#join-guide').onclick=()=>show(3);$('.close').onclick=()=> $('dialog').close();$('#done').onclick=()=> $('dialog').close();